"""Build a portable preview of the ten species and five environments."""
import json
from pathlib import Path
root = Path(__file__).resolve().parents[2]
layouts = json.loads((root/'web/src/pet-frame-layout.json').read_text(encoding='utf-8'))
names = {'cat':'橘白貓','dog':'狗','rabbit':'垂耳兔','hamster':'倉鼠','guinea':'天竺鼠','hedgehog':'刺蝟','ferret':'貂','parrot':'鸚鵡','tortoise':'烏龜','chinchilla':'龍貓'}
html = r'''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>十種寵物與五種場景</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f5f1e9;color:#473b31;font:15px system-ui,sans-serif}main{max-width:1200px;margin:auto;padding:28px 22px}h1{margin:0 0 6px;font-size:27px}p{color:#7a6b5f;line-height:1.6}header{display:flex;justify-content:space-between;gap:16px;align-items:center}small{color:#8a7868}label{display:inline-flex;gap:8px;align-items:center;margin:10px 12px 10px 0}select,button{font:inherit;padding:8px 12px;border:1px solid #dacbbd;border-radius:12px;background:#fffdf9;color:inherit}button{cursor:pointer}#pets{display:grid;grid-template-columns:repeat(auto-fit,minmax(195px,1fr));gap:14px;margin:18px 0 30px}.card{border:1px solid #dfd4c8;border-radius:17px;background:#fffdf8;overflow:hidden}.title{padding:12px 14px;display:flex;justify-content:space-between;font-weight:600}.stage{height:177px;background-size:cover;background-position:center bottom;position:relative;overflow:hidden}.sprite{position:absolute;bottom:12%;left:50%;width:124px;height:124px;transform:translate(-50%,12%);--duration:1.4s}.sprite svg{position:absolute;inset:0;width:100%;height:100%;overflow:hidden;opacity:0;animation:frames var(--duration) step-end infinite}.stage:before{content:'';position:absolute;bottom:12%;left:50%;width:58px;height:7px;transform:translate(-50%,50%);border-radius:50%;background:#61432518}.idle svg{animation-delay:0s!important}.idle svg:nth-child(1){animation-name:open}.idle svg:nth-child(2){animation-name:half}.idle svg:nth-child(3){animation-name:closed}.idle svg:nth-child(4){animation-name:reopen}@keyframes frames{0%{opacity:1}25%,100%{opacity:0}}@keyframes open{0%,94%,100%{opacity:1}88%{opacity:0}}@keyframes half{0%,90%,100%{opacity:0}88%{opacity:1}}@keyframes closed{0%,93%,100%{opacity:0}90%{opacity:1}}@keyframes reopen{0%,94%,100%{opacity:0}93%{opacity:1}}.paused .sprite svg{animation-play-state:paused}#scenes{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}#scenes img{width:100%;display:block;aspect-ratio:16/9;object-fit:cover}h2{font-size:19px}@media(max-width:600px){main{padding:20px 12px}header{display:block}#pets{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.stage{height:154px}.sprite{width:105px;height:105px}h1{font-size:23px}}@media(prefers-reduced-motion:reduce){.sprite svg{animation:none;opacity:0}.sprite svg:first-child{opacity:1}}
</style><main><header><div><h1>十種寵物，五種小世界</h1><p>以圖鑑2的角色為準・每種五套動作・共200幀</p></div><small>透明角色 × 清晰背景</small></header><div><label>動作<select id="pose" aria-label="動作"><option value="idle">待機與眨眼</option><option value="walk" selected>走路</option><option value="eat">進食</option><option value="sleep">睡覺</option><option value="play">玩耍</option></select></label><label>背景<select id="scene" aria-label="背景"><option value="room">小房間</option><option value="garden">庭院</option><option value="beach">海邊</option><option value="gym">健身房</option><option value="space">太空艙</option></select></label><button id="pause">暫停播放</button></div><section id="pets"></section><h2>五種新版背景</h2><section id="scenes"></section><p>原素材保留。每幀依實際輪廓對齊；烏龜與刺蝟步速較慢。App 另有平滑轉場及走路停頓轉向，支援系統「減少動態效果」。</p></main><script>
const layouts=__LAYOUTS__,names=__NAMES__;
const sceneNames={room:'小房間',garden:'庭院',beach:'海邊',gym:'健身房',space:'太空艙'};
function render(){const pose=document.querySelector('#pose').value,scene=document.querySelector('#scene').value;document.querySelector('#pets').innerHTML=Object.entries(names).map(([species,name])=>{const l=layouts[species],base={idle:6.8,walk:.8,eat:2.2,sleep:6,play:2.6}[pose],speed=pose==='walk'?({tortoise:3,hedgehog:1.5,guinea:1.2,parrot:1.2}[species]||1):1;return `<article class="card"><div class="title">${name}<small>4 幀 × 5 動作</small></div><div class="stage" style="background-image:url(scene-${scene}-v2.webp)"><div class="sprite ${pose}" style="--duration:${base*speed}s">${l.poses[pose].map((box,i)=>{const b=l.bounds[pose][i],id=`clip-${species}-${pose}-${i}`;return `<svg viewBox="${box}" style="animation-delay:calc(var(--duration) * ${i?(i-4)/4:0})"><defs><clipPath id="${id}" clipPathUnits="userSpaceOnUse"><rect x="${b.x}" y="${b.y}" width="${b.width}" height="${b.height}"/></clipPath></defs><image href="animated-${species}-v2.webp" width="${l.width}" height="${l.height}" clip-path="url(#${id})"/></svg>`}).join('')}</div></div></article>`}).join('')}
document.querySelector('#scenes').innerHTML=Object.entries(sceneNames).map(([id,name])=>`<article class="card"><img src="scene-${id}-v2.webp" alt="${name}"><div class="title">${name}</div></article>`).join('');document.querySelector('#pose').onchange=render;document.querySelector('#scene').onchange=render;document.querySelector('#pause').onclick=e=>{document.body.classList.toggle('paused');e.target.textContent=document.body.classList.contains('paused')?'繼續播放':'暫停播放'};render();
</script></html>'''
html = html.replace('__LAYOUTS__', json.dumps(layouts)).replace('__NAMES__', json.dumps(names, ensure_ascii=False))
(root/'web/public/pets/animation-preview.html').write_text(html,encoding='utf-8')
print('Preview ready: 10 species / 5 poses / 5 scenes.')
